public class Solution {
    public static int[] reversed(int[] arr) {
        // CONTRACT: return a NEW array, the reverse of arr
        // (arr must be unchanged). arr may have length 0.
        int[] out = new int[arr.length];
        for (int i = 0; i < arr.length; i++) {
            out[i] = arr[i];
        }
        return out;
    }
}

